'use strict';
// Live link regression test. Checks URLs seen in Google Search Console and links generated by the catalog.
const fs = require('node:fs');
const base = 'https://aidiscovertools.com';
const Google = JSON.parse(fs.readFileSync('data/google-search-urls.json', 'utf8'));
const tools = JSON.parse(fs.readFileSync('tools.json', 'utf8').replace(/^\uFEFF/, ''));
const slug = value => String(value).toLowerCase().trim().replace(/&/g,' and ').replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'');
const urls = new Map();
const add = (url, source) => {
  try {
    const u = new URL(url, base);
    if (u.hostname !== 'aidiscovertools.com') return;
    const key = u.toString();
    if (!urls.has(key)) urls.set(key, []);
    urls.get(key).push(source);
  } catch (_) {}
};
for (const url of Google) add(url, 'GSC');
for (const tool of tools) {
  const key = slug(tool.slug || tool.name);
  add('/tools/' + key + '/', 'catalog');
  add('/tools/' + key, 'legacy-clean');
  add('/tool?name=' + key, 'legacy-query');
  add('/tool.html?name=' + key, 'template-query');
}
for (const file of fs.readdirSync('.')) {
  if (file.endsWith('.html')) add('/' + file, 'source-root');
}
for (const extra of ['/', '/sitemap.xml', '/ads.txt', '/robots.txt','/tools/chatgpt.html','/tool.html?name=descript.html']) add(extra, 'critical');
async function check(url, sources) {
  try {
    const response = await fetch(url, {
      signal: AbortSignal.timeout(16000),
      headers: { 'User-Agent':'AI-Discover-Tools-Link-Audit/1.0' }
    });
    const final = new URL(response.url);
    const u = new URL(url);
    let error = '';
    if (!response.ok) error = 'HTTP ' + response.status;
    else if (final.hostname !== 'aidiscovertools.com') error = 'Redirected offsite';
    else if ((u.searchParams.has('name')) && (!final.searchParams.has('name'))) {
      const targetSlug = slug(u.searchParams.get('name').replace(/\.html$/i,''));
      if (final.pathname !== '/tools/' + targetSlug + '/') error = 'Tool name lost during redirect';
    }
    else if (/^\/tools\/.+\/?$/.test(u.pathname) && final.pathname === '/') error = 'Tool redirected to homepage';
    const ctype=response.headers.get('content-type')||'';
    if (response.ok && /\.html?$|\/tools\/|\/tool[?/]?$/.test(u.pathname) && !ctype.includes('text/html')) error = 'Not an HTML page: ' + ctype;
    // A 200 from a generic tool template is not necessarily a usable client-side page; separate audit pending.
    return { url, final:response.url, code:response.status, sources:[...new Set(sources)], error };
  } catch(e) {
    return {url,final:'',code:0,sources:[...new Set(sources)],error:String(e.cause?.message||e.message||e)};
  }
}
(async () => {
  const entries = [...urls.entries()];
  let next=0;
  const result=[];
  async function worker(){
    while(next<entries.length){
      const [url,sources] = entries[next++];
      const r=await check(url,sources);
      result.push(r);
    }
  }
  await Promise.all(Array.from({length:10},worker));
  const failed=result.filter(x=>x.error);
  const byType={};
  for(const f of failed) byType[f.error]=(byType[f.error]||0)+1;
  const out={checked:result.length, failed:failed.length, byType, failures:failed, redirects:result.filter(x=>x.url!==x.final).slice(0,100)};
  fs.writeFileSync('live-link-audit-report.json',JSON.stringify(out,null,2));
  console.log('LINK AUDIT: '+result.length+' URLs checked; '+failed.length+' failures.');
  console.log('BY ERROR: '+JSON.stringify(byType));
  for(const item of failed.slice(0,90)) console.log('BROKEN '+item.code+' '+item.url+' -> '+item.final+' ['+item.error+']');
  for(const item of result.filter(x=>x.url!==x.final && !x.error).slice(0,30)) console.log('REDIRECT '+item.url+' -> '+item.final);
  if(process.env.GITHUB_STEP_SUMMARY) fs.appendFileSync(process.env.GITHUB_STEP_SUMMARY,
    '# Link audit\n\nChecked '+result.length+' URLs, '+failed.length+' problems.\n\n' +
    failed.slice(0,35).map(f=>'- '+f.url+': '+f.error).join('\n')+'\n');
  if(failed.length) process.exitCode=1;
})().catch(e=>{console.error(e);process.exitCode=1});
